int MOD = 998244353;

long long calculate(const string &A, int index, int prev, int v) {
    if (index == (int)A.size()) {
        return prev == 0 ? 1 : 0;
    }
    if (memoization[index][prev][v] != -1) {
        return memoization[index][prev][v];
    }
    long long result = 0;
    if (A[index] == '_') {
        for (int j = 0; j < 10; j++) {
            if (index == 0 && j == 0) continue;
            int newPrev = (prev * 10 + j) % 25;
            result += calculate(A, index + 1, newPrev, v);
        }
    } else if (A[index] == 'X') {
        if (v != 10) {
            result += calculate(A, index + 1, (prev * 10 + v) % 25, v);
        } else {
            for (int j = 0; j < 10; j++) {
                if (index == 0 && j == 0) continue;
                int newPrev = (prev * 10 + j) % 25;
                result += calculate(A, index + 1, newPrev, j);
            }
        }
    } else {
        int digit = A[index] - '0';
        result += calculate(A, index + 1, (prev * 10 + digit) % 25, v);
    }
    return memoization[index][prev][v] = result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int testCount = 1;
